(function(){'use strict';const C=Critters,R=CritterRenderer.prototype,portrait=C.drawHeroPortrait,worm=R.worm,event=R.event,effects=R.effects;const setGame=R.setGame;R.setGame=function(g,lobby){setGame.call(this,g,lobby);this.heroRevives=[];};const atlas=new Image(),waiting=new Map();
function art(k,index,w,h){if(!atlas.complete||!atlas.naturalWidth)waiting.set(k.canvas,{index,w,h});k.clearRect(0,0,w,h);k.save();k.beginPath();k.roundRect(0,0,w,h,Math.min(w,h)*.14);k.clip();k.fillStyle='#101c35';k.fillRect(0,0,w,h);if(atlas.complete&&atlas.naturalWidth){const cw=atlas.naturalWidth/7,ch=atlas.naturalHeight/4,size=Math.min(w,h);k.drawImage(atlas,(index%7)*cw,Math.floor(index/7)*ch,cw,ch,(w-size)/2,(h-size)/2,size,size);}else{k.fillStyle='#74d9eb';k.beginPath();k.ellipse(w/2,h/2,w*.2,h*.3,-.4,0,7);k.fill();}k.restore();return true;}
C.drawWeaponCardIcon=art;C.createWeaponArt=function(w){const c=document.createElement('canvas');c.width=240;c.height=180;c.className='weapon-art';c.setAttribute('role','img');c.setAttribute('aria-label',w.name+' 3D 이미지');art(c.getContext('2d'),C.WEAPONS.findIndex(x=>x.id===w.id),240,180);return c;};
C.createSkillArt=function(h){const ids={scout:0,bunny:8,iron:2,dragon:15,guardian:13,twin:6,ninja:12,medic:24,polar:18,bee:25,pirate:16,astral:23,parasite:26,archangel:27},c=document.createElement('canvas');c.width=c.height=120;c.className='hero-skill-icon';c.title=h.skill;c.setAttribute('role','img');c.setAttribute('aria-label',h.name+' 능력: '+h.skill);art(c.getContext('2d'),ids[h.id]??0,120,120);return c;};
atlas.onload=()=>{for(const [canvas,d]of waiting)if(canvas.isConnected)art(canvas.getContext('2d'),d.index,d.w,d.h);else waiting.delete(canvas);waiting.clear();const body=document.getElementById('metaBody'),layer=document.getElementById('metaLayer');if(layer&&!layer.hidden){const scroll=body.scrollTop;PCMeta.refresh();body.scrollTop=scroll;}window.dispatchEvent(new Event('pc:art-ready'));};atlas.src='hero-atlas.jpg';
function diamond(k,x,y,size,color){k.save();k.translate(x,y);k.fillStyle=color;k.strokeStyle='#fff0b4';k.lineWidth=1;k.beginPath();k.moveTo(0,-size);k.lineTo(size*.75,0);k.lineTo(0,size);k.lineTo(-size*.75,0);k.closePath();k.fill();k.stroke();k.restore();}
function wings(k,x,y,size,time){k.save();k.translate(x,y);k.scale(size,size);for(const side of [-1,1]){k.save();k.scale(side,1);k.fillStyle='#f4eddb';k.strokeStyle='#c7ac77';k.lineWidth=1.1;for(let i=0;i<5;i++){k.beginPath();k.moveTo(3,2+i*2);k.quadraticCurveTo(20+i*4,-14-i*3+Math.sin(time)*2,37-i*4,-22+i*5);k.quadraticCurveTo(24-i,-2+i*3,4,14);k.fill();k.stroke();}k.restore();}k.restore();}
function cape(k,x,y,face,size,time,color){k.save();k.translate(x,y);k.scale(face*size,size);k.fillStyle=color;k.strokeStyle='#b8d9e077';k.lineWidth=1;k.beginPath();k.moveTo(-7,-16);k.quadraticCurveTo(-25,-2,-42,4+Math.sin(time*3)*4);k.lineTo(-32,31);k.quadraticCurveTo(-14,23,-4,10);k.closePath();k.fill();k.stroke();k.restore();}
C.drawHeroPortrait=function(k,h,w=160,height=110){portrait.call(this,k,h,w,height);const s=Math.min(w/150,height/125),x=w*.51,y=height*.68;k.save();k.globalCompositeOperation='destination-over';if(h.id==='archangel')wings(k,x,y-23*s,s*1.35,0);else cape(k,x,y,1,s,0,h.id==='parasite'?'#4f356d':'#23476f');k.restore();k.save();k.translate(x,y);k.scale(s,s);if(h.id==='parasite'){k.strokeStyle='#a5ec73';k.lineWidth=3;for(let i=0;i<4;i++){k.beginPath();k.moveTo(-9,12-i*9);k.bezierCurveTo(-48,20-i*8,-23,-29-i*3,-44,-33+i*10);k.stroke();}k.fillStyle='#4a3d68';k.beginPath();k.moveTo(-16,-55);k.lineTo(-12,-71);k.lineTo(1,-60);k.lineTo(19,-70);k.lineTo(23,-48);k.quadraticCurveTo(0,-56,-16,-48);k.closePath();k.fill();diamond(k,4,-3,10,'#b5fa78');}else{const gr=k.createLinearGradient(-15,-12,20,14);gr.addColorStop(0,'#c1edee');gr.addColorStop(.4,'#386c8b');gr.addColorStop(1,'#173454');k.fillStyle=h.id==='archangel'?'#fff0d0':gr;k.strokeStyle='#e2bb71';k.lineWidth=1.4;k.beginPath();k.moveTo(-10,-17);k.lineTo(21,-13);k.lineTo(22,8);k.lineTo(6,18);k.lineTo(-10,7);k.closePath();k.fill();k.stroke();diamond(k,7,-1,8,h.id==='archangel'?'#f7d782':'#8bf3f7');if(h.id==='archangel'){k.strokeStyle='#ffdf8a';k.lineWidth=3;k.beginPath();k.ellipse(6,-72,22,5,0,0,7);k.stroke();}}k.restore();};
R.worm=function(k,u,s=1,labels=false){if(u.landing)return worm.call(this,k,u,s,labels);if(u.character==='archangel')wings(k,u.x,u.y-9,s,this.reduced?0:this.time*3);else cape(k,u.x,u.y,u.face||1,s,this.reduced?0:this.time+u.id,u.character==='parasite'?'#543963':u.team?'#773b58':'#264f7b');k.save();if(u.reviveGrace>0)k.globalAlpha=.35+.65*(1-u.reviveGrace/.85);worm.call(this,k,u,s,labels);k.restore();k.save();k.translate(u.x,u.y);k.scale((u.face||1)*s,s);k.fillStyle=u.character==='archangel'?'#f9e4b5':u.character==='parasite'?'#574269':'#2b617c';k.strokeStyle='#dfc584';k.lineWidth=1;k.beginPath();k.moveTo(-6,-12);k.lineTo(12,-10);k.lineTo(12,5);k.lineTo(4,11);k.lineTo(-7,5);k.closePath();k.fill();k.stroke();diamond(k,3,-1,4,u.character==='parasite'?'#bdff7a':u.character==='archangel'?'#fff0a7':'#98ffff');if(u.character==='archangel'){k.strokeStyle='#ffe29a';k.lineWidth=2;k.beginPath();k.ellipse(4,-49,17,4,0,0,7);k.stroke();}if(u.character==='parasite'){k.strokeStyle='#b5ed7d';k.lineWidth=2;for(let i=0;i<3;i++){k.beginPath();k.moveTo(-8,1+i*5);k.quadraticCurveTo(-30,14+Math.sin(this.time*3+i)*5,-24,-7-i*8);k.stroke();}}k.restore();};
R.event=function(e){event.call(this,e);if(e.type==='heroRevive'){this.heroRevives??=[];this.heroRevives.push({id:e.id,life:1.4});this.texts.push({x:e.x,y:e.y-65,text:'부활! HP '+e.hp,life:1.8,color:'#fff1ac'});}if(e.type==='parasiteBurst'){this.rings.push({x:e.x,y:e.y,r:e.r,life:.65,max:.65});this.shake=this.reduced?0:8;for(let i=0;i<40;i++)this.fx.push({x:e.x,y:e.y,vx:(Math.random()-.5)*240,vy:(Math.random()-.7)*220,life:.8,max:.8,size:3+Math.random()*6,color:i%2?'#bbec7a':'#b1a0e3',type:'debris'});}};
R.effects=function(k,dt){effects.call(this,k,dt);for(const r of this.heroRevives||[]){if(!this.game.paused)r.life-=dt;const u=this.game.units[r.id];k.save();k.globalAlpha=Math.max(0,r.life/1.4);const gr=k.createLinearGradient(u.x,u.y-160,u.x,u.y+20);gr.addColorStop(0,'#fff0bb00');gr.addColorStop(.8,'#fff2bba0');gr.addColorStop(1,'#fff8dfdd');k.fillStyle=gr;k.fillRect(u.x-27,u.y-160,54,180);k.strokeStyle='#ffe9a8';k.lineWidth=3;k.beginPath();k.ellipse(u.x,u.y+15,32+(1.4-r.life)*16,9,0,0,7);k.stroke();wings(k,u.x,u.y-65,1.3,0);k.restore();}this.heroRevives=(this.heroRevives||[]).filter(r=>r.life>0);};
const backdrop=document.createElement('div');backdrop.id='heroBackdrop';backdrop.innerHTML='<div class="hero-city-glow"></div>';document.getElementById('app').prepend(backdrop);document.querySelector('.home-title').innerHTML='<span class="home-kicker">NIGHTFALL SQUAD</span><h1>웜 히어로즈<span>밤을 지키는 작은 영웅들</span></h1>';const cover=document.createElement('img');cover.id='heroKeyArt';cover.src='hero-cover.jpg';cover.alt='밤의 도시에서 집결한 웜 히어로 팀';document.querySelector('.home-showcase').prepend(cover);document.querySelector('.home-nav>.section-label').textContent='HERO BASE';document.querySelector('.crew-caption b').textContent='히어로 팀 출동 대기';document.querySelector('.crew-caption>span').textContent='각각의 능력으로 만드는 3인 팀';document.querySelector('.expedition-card .section-label').innerHTML='NIGHTFALL CAMPAIGN <span>'+C.STAGES.length+' STAGES</span>';document.querySelector('#campaignOpen span').textContent='영웅 작전 시작';document.querySelector('.home-title').setAttribute('aria-label','웜 히어로즈 · 밤을 지키는 작은 영웅들');document.body.classList.add('hero-theme');window.dispatchEvent(new Event('pc:wallet-changed'));
})();
